const hero=document.querySelector('.cinema-hero'),wall=document.querySelector('.film-wall'),motionToggle=document.querySelector('#motion-toggle');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function updateMotionLabel(){motionToggle.setAttribute('aria-label',t(hero.dataset.paused==='true'?'play':'pause'));const note=document.querySelector('.film-loading-note');if(note)note.textContent=t('loadError');}
function setMotion(paused){hero.dataset.paused=String(paused);motionToggle.setAttribute('aria-pressed',String(paused));updateMotionLabel();}
setMotion(motionPreference.matches);motionToggle.addEventListener('click',()=>setMotion(hero.dataset.paused!=='true'));motionPreference.addEventListener('change',event=>setMotion(event.matches));document.addEventListener('localechange',updateMotionLabel);
async function buildCinema(){
const response=await fetch('films.json');if(!response.ok)throw Error('Film archive unavailable');const frames=await response.json();if(!frames.length)throw Error('Film archive empty');
for(let row=0;row<6;row++){const track=document.createElement('div');track.className='film-row';track.style.setProperty('--duration',(110+row*17)+'s');track.style.animationDelay='-'+(row*19+8)+'s';const group=document.createElement('div');group.className='film-group';for(let col=0;col<24;col++){const frame=frames[(col*7+row*5)%frames.length],cell=document.createElement('div');cell.className='film-cell';const img=new Image();img.alt='';img.src=frame.src;img.decoding='async';img.draggable=false;cell.append(img);group.append(cell);}track.append(group,group.cloneNode(true));wall.append(track);}
const credits=document.querySelector('.film-credits');
for(const film of [...new Set(frames.map(frame=>frame.en))]){const collection=frames.filter(frame=>frame.en===film),block=document.createElement('section');block.className='film-credit-group';const heading=document.createElement('h3');heading.dataset.filmTitle=film;heading.textContent=t('filmTitles')[film]||film;const thumbs=document.createElement('div');thumbs.className='credit-thumbs';collection.forEach(frame=>{const a=document.createElement('a');a.href=frame.source;a.target='_blank';a.rel='noopener noreferrer';a.dataset.film=film;a.setAttribute('aria-label',t('sourceLink')+': '+heading.textContent);a.title=a.getAttribute('aria-label');const img=new Image();img.src=frame.src;img.alt='';img.loading='lazy';a.append(img);thumbs.append(a);});block.append(heading,thumbs);credits.append(block);}
}
buildCinema().catch(()=>{wall.classList.add('static-fallback');motionToggle.disabled=true;const note=document.createElement('p');note.className='film-loading-note';note.textContent=t('loadError');hero.append(note);});
